// TestStringLiteral: let s = "hello"
func TestStringLiteral(t *testing.T) {
    _, globals := runProgram(t, `let s = "hello"`)
    if sVal, ok := globals["s"]; !ok || sVal.Kind != KindString || sVal.SVal != "hello" {
